/**
 * Accessly — Real User Monitoring (RUM) agent
 * Embed: <script src="/rum.min.js?site_key=YOUR_SITE_KEY" defer></script>
 *
 * Lightweight, non-blocking Real User Monitoring. Collects page views,
 * Core Web Vitals, AJAX, JS errors and resource timing, batches them, and
 * ships via navigator.sendBeacon (fetch keepalive fallback). Everything is
 * wrapped so it can never break the host site — it fails silently.
 */
(function () {
  'use strict';
  try {
    var s = document.currentScript || (function () {
      var t = document.getElementsByTagName('script');
      return t[t.length - 1];
    })();
    var src = s ? (s.src || '') : '';
    var KEY = new URLSearchParams(src.split('?')[1] || '').get('site_key') || '';
    if (!KEY) return;
    var BASE = src ? src.split('/rum.min.js')[0] : '';
    var ENDPOINT = BASE + '/api/rum';

    var win = window, doc = document, nav = navigator;
    var perf = win.performance;
    var now = function () { return perf && perf.now ? perf.now() : Date.now(); };

    // ── ids ───────────────────────────────────────────────────
    function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 10); }
    var SID;
    try {
      SID = sessionStorage.getItem('_accessly_rum_sid');
      if (!SID) { SID = uid(); sessionStorage.setItem('_accessly_rum_sid', SID); }
    } catch (e) { SID = uid(); }
    var PVID = uid();

    // ── environment ───────────────────────────────────────────
    var BR = 'Unknown', BV = '', OS = 'Unknown', DV = 'desktop', CN = '';
    try {
      var u = nav.userAgent || '';
      var m;
      if ((m = u.match(/Edg\/(\d+)/))) { BR = 'Edge'; BV = m[1]; }
      else if ((m = u.match(/OPR\/(\d+)/)) || (m = u.match(/Opera[ /](\d+)/))) { BR = 'Opera'; BV = m[1]; }
      else if ((m = u.match(/Chrome\/(\d+)/))) { BR = 'Chrome'; BV = m[1]; }
      else if ((m = u.match(/Firefox\/(\d+)/))) { BR = 'Firefox'; BV = m[1]; }
      else if (/Safari\//.test(u)) { BR = 'Safari'; m = u.match(/Version\/(\d+(?:\.\d+)?)/); BV = m ? m[1] : ''; }
      if (/Windows/.test(u)) OS = 'Windows';
      else if (/Android/.test(u)) OS = 'Android';
      else if (/iPhone|iPad|iPod/.test(u)) OS = 'iOS';
      else if (/Mac OS X/.test(u)) OS = 'macOS';
      else if (/Linux/.test(u)) OS = 'Linux';
      if (/iPad|Tablet/.test(u)) DV = 'tablet';
      else if (/Mobi|Android|iPhone|iPod/.test(u)) DV = 'mobile';
      var conn = nav.connection || nav.mozConnection || nav.webkitConnection;
      if (conn && conn.effectiveType) CN = conn.effectiveType;
    } catch (e) {}

    // View state — supports SPA soft navigations: every route change is a page view.
    var viewPath = location.pathname;
    var viewStart = Date.now();
    var viewStartPerf = now();          // performance.now() domain — aligns with paint entries
    var firstView = true;               // load-time metrics only apply to the first view
    var segCls = 0, segInp = 0;         // per-view CLS accumulation & max interaction (INP)
    // SPA route-transition metrics. Native FCP/LCP are document-navigation metrics
    // that DO NOT restart on client-side navigation, so for soft navigations we
    // record a clearly-labelled custom measurement instead of faking native values:
    //   spaFcp = time from route change to the next painted frame (double rAF) — reliable.
    //   spaLcp = best-effort: LCP entries emitted after the route change (usually none,
    //            because native LCP stops after the first interaction) — may be null.
    var viewSpaFcp = null, viewSpaLcp = null, spaLcpObs = null;
    var metrics = { ttfb: null, fcp: null, lcp: null, di: null, dcl: null, lt: null };
    var qA = [], qE = [], qR = [];      // ajax, errors, resources queues

    function stripQuery(v) {
      try { var x = new URL(v, location.href); return x.origin + x.pathname; }
      catch (e) { return ('' + v).split('?')[0]; }
    }

    // ── transport ─────────────────────────────────────────────
    function send(body) {
      try {
        var json = JSON.stringify(body);
        // text/plain keeps this a CORS "simple request" (no preflight), so the
        // beacon works cross-origin from the customer's domain. The endpoint
        // reads the raw text and JSON-parses it.
        if (nav.sendBeacon) {
          var blob = new Blob([json], { type: 'text/plain;charset=UTF-8' });
          if (nav.sendBeacon(ENDPOINT, blob)) return;
        }
        if (win.fetch) {
          fetch(ENDPOINT, { method: 'POST', body: json, keepalive: true, mode: 'cors', headers: { 'Content-Type': 'text/plain;charset=UTF-8' } }).catch(function () {});
        }
      } catch (e) {}
    }

    function flush(includePage) {
      try {
        var body = { k: KEY, s: SID, v: PVID };
        var any = false;
        if (qA.length) { body.a = qA.splice(0, qA.length); any = true; }
        if (qE.length) { body.e = qE.splice(0, qE.length); any = true; }
        if (qR.length) { body.r = qR.splice(0, qR.length); any = true; }
        if (includePage) { body.p = buildPage(); any = true; }
        if (any) send(body);
      } catch (e) {}
    }

    function buildPage() {
      // Load-time metrics (TTFB/FCP/LCP/DOM timing) only apply to the initial view.
      var lm = firstView ? metrics : { ttfb: null, fcp: null, lcp: null, di: null, dcl: null, lt: null };
      return {
        id: PVID, path: viewPath, ref: doc.referrer || null,
        br: BR, bv: BV, cn: CN, os: OS, dv: DV, vw: win.innerWidth || null, vh: win.innerHeight || null,
        dur: Date.now() - viewStart,
        nt: firstView ? 'initial' : 'spa',
        ttfb: lm.ttfb, fcp: lm.fcp, lcp: lm.lcp,
        sfcp: viewSpaFcp, slcp: viewSpaLcp,
        inp: segInp || null, cls: Math.round(segCls * 1000) / 1000,
        di: lm.di, dcl: lm.dcl, lt: lm.lt
      };
    }

    // Measure the SPA route-transition render: time from the route change to the
    // next painted frame. Double rAF fires after the browser has painted the new
    // route's DOM. One-shot (not a loop) — negligible overhead.
    function measureSpaPaint() {
      var t0 = viewStartPerf;
      try {
        win.requestAnimationFrame(function () {
          win.requestAnimationFrame(function () { viewSpaFcp = round(now() - t0); });
        });
      } catch (e) {}
    }
    // Best-effort SPA "LCP": a fresh per-route LCP observer. Native LCP normally
    // stops after the first interaction (the click that triggered navigation), so
    // this is usually null — we never fabricate a value. Disconnected on next route.
    function measureSpaLcp() {
      try { if (spaLcpObs) spaLcpObs.disconnect(); } catch (e) {}
      viewSpaLcp = null;
      try {
        spaLcpObs = new PerformanceObserver(function (l) {
          var es = l.getEntries(); var last = es[es.length - 1];
          if (last) viewSpaLcp = Math.max(0, round((last.renderTime || last.loadTime || last.startTime) - viewStartPerf));
        });
        spaLcpObs.observe({ type: 'largest-contentful-paint', buffered: false });
      } catch (e) {}
    }

    // ── navigation timing ─────────────────────────────────────
    function readNav() {
      try {
        var e = perf && perf.getEntriesByType && perf.getEntriesByType('navigation')[0];
        if (e) {
          metrics.ttfb = round(e.responseStart);
          metrics.di = round(e.domInteractive);
          metrics.dcl = round(e.domContentLoadedEventEnd);
          metrics.lt = round(e.loadEventEnd || e.duration);
        }
      } catch (e) {}
    }
    function round(n) { return (n == null || isNaN(n)) ? null : Math.round(n); }

    // ── PerformanceObservers (feature-detected) ───────────────
    function observe(type, cb, opts) {
      try {
        var o = new PerformanceObserver(function (list) { try { cb(list); } catch (e) {} });
        var conf = { type: type, buffered: true };
        if (opts) for (var k in opts) conf[k] = opts[k];
        o.observe(conf);
        return o;
      } catch (e) { return null; }
    }

    observe('paint', function (l) {
      l.getEntries().forEach(function (en) { if (en.name === 'first-contentful-paint') metrics.fcp = round(en.startTime); });
    });
    var lcpO = observe('largest-contentful-paint', function (l) {
      var es = l.getEntries(); var last = es[es.length - 1];
      if (last) metrics.lcp = round(last.renderTime || last.loadTime || last.startTime);
    });
    observe('layout-shift', function (l) {
      l.getEntries().forEach(function (en) { if (!en.hadRecentInput) segCls += en.value; });
    });
    observe('event', function (l) {
      l.getEntries().forEach(function (en) {
        if (en.interactionId && en.duration > segInp) segInp = Math.round(en.duration);
      });
    }, { durationThreshold: 40 });
    observe('resource', function (l) {
      l.getEntries().forEach(function (en) {
        if (qR.length < 60) {
          qR.push({ u: stripQuery(en.name), rt: en.initiatorType || null, d: round(en.duration), ts: Math.round(en.transferSize || 0), st: round(en.startTime) });
        }
      });
    });

    // ── JS errors ─────────────────────────────────────────────
    win.addEventListener('error', function (ev) {
      try {
        if (!ev || (!ev.message && !ev.error)) return;
        qE.push({
          m: (ev.message || 'Error').slice(0, 500),
          t: (ev.error && ev.error.name) || 'Error',
          st: ((ev.error && ev.error.stack) || '').slice(0, 2000),
          u: ev.filename || null, ln: ev.lineno || null, cn: ev.colno || null, p: location.pathname
        });
        if (qE.length >= 20) flush(false);
      } catch (e) {}
    }, true);
    win.addEventListener('unhandledrejection', function (ev) {
      try {
        var r = ev && ev.reason;
        qE.push({
          m: ((r && r.message) || String(r) || 'Unhandled rejection').slice(0, 500),
          t: 'UnhandledRejection', st: ((r && r.stack) || '').slice(0, 2000),
          u: null, ln: null, cn: null, p: location.pathname
        });
      } catch (e) {}
    });

    // ── AJAX: fetch + XHR (transparent, always call original) ──
    function record(url, method, status, start, res, xhr) {
      try {
        var su = stripQuery(url);
        if (su.indexOf('/api/rum') > -1) return; // never monitor our own beacons
        var dur = now() - start;
        var size = null;
        try {
          if (res && res.headers) { var cl = res.headers.get('content-length'); if (cl) size = +cl; }
          else if (xhr && xhr.getResponseHeader) { var clx = xhr.getResponseHeader('content-length'); if (clx) size = +clx; }
        } catch (e) {}
        qA.push({ u: su, mt: (method || 'GET').toUpperCase(), sc: status, d: Math.round(dur), ok: status >= 200 && status < 400, sz: size });
        if (qA.length >= 20) flush(false);
      } catch (e) {}
    }

    try {
      var of = win.fetch;
      if (of) {
        win.fetch = function (input, init) {
          var start = now();
          var url = (typeof input === 'string') ? input : (input && input.url) || '';
          var method = (init && init.method) || (input && input.method) || 'GET';
          return of.apply(this, arguments).then(function (resp) {
            record(url, method, resp.status, start, resp);
            return resp;
          }, function (err) { record(url, method, 0, start, null); throw err; });
        };
      }
    } catch (e) {}

    try {
      var XP = win.XMLHttpRequest && win.XMLHttpRequest.prototype;
      if (XP && XP.open && XP.send) {
        var oOpen = XP.open, oSend = XP.send;
        XP.open = function (m, u) { try { this.__rum = { m: m, u: u }; } catch (e) {} return oOpen.apply(this, arguments); };
        XP.send = function () {
          try {
            // eslint-disable-next-line @typescript-eslint/no-this-alias
            var self = this;
            if (self.__rum) {
              var start = now();
              self.addEventListener('loadend', function () { record(self.__rum.u, self.__rum.m, self.status, start, null, self); });
            }
          } catch (e) {}
          return oSend.apply(this, arguments);
        };
      }
    } catch (e) {}

    // ── SPA route changes ─────────────────────────────────────
    // On a client-side navigation, finalize the current view as a page view
    // and start a fresh one (new id, timer, and per-view CLS/INP).
    function onRouteChange() {
      try {
        var np = location.pathname;
        if (np === viewPath) return;   // ignore query/hash-only changes
        readNav();
        flush(true);                   // send the finishing view + any queued telemetry
        firstView = false;
        PVID = uid();
        viewPath = np;
        viewStart = Date.now();
        viewStartPerf = now();
        segCls = 0; segInp = 0;
        viewSpaFcp = null; viewSpaLcp = null;
        measureSpaPaint();             // one-shot double-rAF → spa route render time
        measureSpaLcp();               // best-effort post-nav LCP observer
      } catch (e) {}
    }
    try {
      ['pushState', 'replaceState'].forEach(function (t) {
        var orig = history[t];
        if (typeof orig === 'function') {
          history[t] = function () {
            var r = orig.apply(this, arguments);
            setTimeout(onRouteChange, 0);
            return r;
          };
        }
      });
      win.addEventListener('popstate', function () { setTimeout(onRouteChange, 0); });
    } catch (e) {}

    // ── lifecycle ─────────────────────────────────────────────
    win.addEventListener('DOMContentLoaded', readNav);
    win.addEventListener('load', function () { setTimeout(readNav, 0); });
    var iv = setInterval(function () { flush(false); }, 15000);

    var sent = false;
    function finalFlush() {
      if (sent) return; sent = true;
      readNav();
      try { if (lcpO && lcpO.takeRecords) lcpO.takeRecords(); } catch (e) {}
      flush(true);
      try { clearInterval(iv); } catch (e) {}
    }
    win.addEventListener('visibilitychange', function () { if (doc.visibilityState === 'hidden') finalFlush(); });
    win.addEventListener('pagehide', finalFlush);
  } catch (e) { /* fail silently — never break the host site */ }
})();
